// Functions receive shared services and state through an explicit application context.
export function install(ctx){
function login(){ ctx.$('#app').innerHTML=`<main class="login"><section class="login-art">${ctx.brand()}<div><div class="eyebrow">Da sua ideia à produção</div><h1>Seu negócio organizado.<br><em>Suas ideias em movimento.</em></h1><p>Clientes, produtos e orçamentos em um só lugar. Mais clareza para cuidar de cada detalhe da sua confecção.</p></div><footer class="eyebrow">AVELON TÊXTIL · GESTÃO QUE ACOMPANHA VOCÊ</footer></section><section class="login-form"><div class="login-box"><div class="eyebrow">Sistema Avelon</div><h2>Bem-vindo à Avelon.</h2><p class="muted">Entre para acessar sua área de trabalho.</p><form id="login-form">${ctx.field('Usuário ou e-mail','identity','text','', 'required autocomplete="username" placeholder="Seu usuário"')}${ctx.field('Senha','password','password','','required autocomplete="current-password" placeholder="Sua senha"')}<p id="login-error" role="alert"></p><button class="primary wide" type="submit">Entrar no sistema ${ctx.icon('arrow')}</button></form><button class="ghost wide small" id="recover">Esqueci minha senha</button><div class="login-footer">${ctx.icon('lock')} Seu espaço de gestão, com acesso protegido.<br>© ${new Date().getFullYear()} Avelon Têxtil</div></div></section></main>`;
 ctx.$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;ctx.$('#login-error').textContent='';const f=new FormData(e.target);let identity=f.get('identity').trim().toLowerCase();if(identity===ctx.config.username)identity=ctx.config.email;try{const s=await ctx.api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:{email:identity,password:f.get('password')}});ctx.saveSession({...s,expires_at:Date.now()/1000+s.expires_in});e.target.reset();await ctx.load();ctx.render('home')}catch(err){ctx.$('#login-error').className='error';ctx.$('#login-error').textContent=err.message.includes('Invalid login')?'Usuário ou senha não conferem.':err.message}finally{b.disabled=false}};
 const sign=document.createElement('button');sign.className='secondary wide small';sign.textContent='Solicitar novo acesso';ctx.$('#recover').after(sign);sign.onclick=ctx.signupDialog;
 ctx.$('#recover').onclick=async()=>{const identity=ctx.$('[name=identity]').value.trim().toLowerCase();if(!identity)return ctx.toast('Informe seu usuário ou e-mail primeiro.');try{await ctx.api('/auth/v1/recover',{method:'POST',auth:false,body:{email:identity===ctx.config.username?ctx.config.email:identity,redirect_to:location.href.split('#')[0]}});ctx.toast('Se o e-mail estiver cadastrado, você receberá instruções de recuperação.')}catch(e){ctx.toast(e.message)}};
}

function passwordDialog(){const d=document.createElement('dialog');d.innerHTML=`<h2>Definir senha pessoal</h2><p class="muted">Escolha uma senha de pelo menos 10 caracteres para proteger seu acesso.</p><form id="password-form">${ctx.field('Nova senha','password','password','','required minlength="10" autocomplete="new-password"')}${ctx.field('Confirmar nova senha','confirmation','password','','required minlength="10" autocomplete="new-password"')}<p id="password-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" id="close-password">Cancelar</button><button class="primary" type="submit">Atualizar senha</button></div></form>`;document.body.append(d);d.showModal();ctx.$('#close-password').onclick=()=>d.close();d.onclose=()=>d.remove();ctx.$('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('password')!==f.get('confirmation')){ctx.$('#password-error').textContent='As senhas precisam ser iguais.';return}e.submitter.disabled=true;try{await ctx.api('/auth/v1/user',{method:'PUT',body:{password:f.get('password'),data:{username:ctx.profile?.username||ctx.config.username,password_changed:true}}});d.close();ctx.toast('Senha pessoal atualizada.')}catch(err){ctx.$('#password-error').textContent=err.message;e.submitter.disabled=false}}}

async function start(){const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('access_token')){ctx.saveSession({access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token'),expires_at:Date.now()/1000+Number(hash.get('expires_in')||3600)});history.replaceState(null,'',location.pathname);try{await ctx.load();ctx.render('home');ctx.passwordDialog()}catch(e){ctx.login();ctx.toast(e.message)}return}if(!ctx.session){ctx.login();return}try{await ctx.load();ctx.render('home')}catch(e){ctx.saveSession(null);ctx.login();ctx.toast('Entre novamente para continuar.')}}

function signupDialog(){const d=document.createElement('dialog');d.innerHTML=`<h2>Solicitar novo acesso</h2><p class="muted">Seu cadastro precisa de confirmação de e-mail e aprovação do administrador. Ele não libera acesso aos dados de outros usuários.</p><form id="signup-form">${ctx.field('Nome de usuário','username','text','','required minlength="3" maxlength="40" pattern="[A-Za-z0-9_]+"')}${ctx.field('E-mail','email','email','','required autocomplete="email"')}${ctx.field('Senha pessoal','password','password','','required minlength="10" autocomplete="new-password"')}<p id="signup-message" role="alert"></p><div class="form-actions"><button class="secondary" type="button" id="close-signup">Cancelar</button><button class="primary" type="submit">Solicitar cadastro</button></div></form>`;document.body.append(d);d.showModal();ctx.$('#close-signup').onclick=()=>d.close();d.onclose=()=>d.remove();ctx.$('#signup-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const f=new FormData(e.target);try{await ctx.api('/auth/v1/signup',{method:'POST',auth:false,body:{email:f.get('email'),password:f.get('password'),data:{username:f.get('username')}}});e.target.reset();ctx.$('#signup-message').textContent='Solicitação recebida. Confira seu e-mail para confirmar o endereço. Após a confirmação, aguarde a aprovação do administrador.'}catch(err){ctx.$('#signup-message').textContent=err.message}finally{e.submitter.disabled=false}}}
Object.assign(ctx,{login,passwordDialog,start,signupDialog});
}
